function serializeFacets(rows) {
  const hasOwn = Object.prototype.hasOwnProperty;

  function isPlainObject(value) {
    if (value === null || typeof value !== "object") return false;
    const prototype = Object.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
  }

  function encode(value) {
    return encodeURIComponent(value).replace(/[!'()*]/g, function (char) {
      return "%" + char.charCodeAt(0).toString(16).toUpperCase();
    });
  }

  if (!Array.isArray(rows)) {
    throw new TypeError("rows must be an array");
  }

  const pairs = [];

  for (let i = 0; i < rows.length; i++) {
    if (!hasOwn.call(rows, i)) {
      throw new TypeError("rows must be dense");
    }

    const row = rows[i];

    if (
      !isPlainObject(row) ||
      !hasOwn.call(row, "name") ||
      !hasOwn.call(row, "values") ||
      typeof row.name !== "string" ||
      !Array.isArray(row.values)
    ) {
      throw new TypeError("invalid facet row");
    }

    const encodedName = encode(row.name);
    const values = row.values;

    for (let j = 0; j < values.length; j++) {
      if (!hasOwn.call(values, j) || typeof values[j] !== "string") {
        throw new TypeError("values must be a dense array of strings");
      }

      pairs.push([encodedName, encode(values[j])]);
    }
  }

  pairs.sort(function (a, b) {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(function (pair) {
    return pair[0] + "=" + pair[1];
  }).join("&");
}
